-- 卷一（周纪一）112 段正文不再由本脚本初始化：正文属于数据，随 db/history-book.mv.db 数据文件分发。
-- 全新空库不再内置卷一正文，可在「数据同步」页面从 dutongjian.com 导入。

INSERT INTO "TJ_SYNC_STATE"(ID,TOTAL_REIGNS,COMPLETED_REIGNS,CONTENT_COUNT,STATUS,MESSAGE,UPDATE_TIME)
SELECT * FROM (VALUES
(1,1405,30,112,'0','已内置卷一正文，其余纪年可在数据同步页面继续导入',CURRENT_TIMESTAMP)
) AS V(ID,TOTAL_REIGNS,COMPLETED_REIGNS,CONTENT_COUNT,STATUS,MESSAGE,UPDATE_TIME)
WHERE NOT EXISTS (SELECT 1 FROM "TJ_SYNC_STATE");

-- 自增序列对齐到 MAX+1（显式 ID 种子不会推进序列；写死值会在已有数据后回退序列导致主键冲突，故用子查询幂等重置）
ALTER TABLE "TJ_VOLUME" ALTER COLUMN "VOLUME_ID" RESTART WITH (SELECT COALESCE(MAX(VOLUME_ID),0)+1 FROM "TJ_VOLUME");
ALTER TABLE "TJ_REIGN" ALTER COLUMN "REIGN_ID" RESTART WITH (SELECT COALESCE(MAX(REIGN_ID),0)+1 FROM "TJ_REIGN");
ALTER TABLE "TJ_CONTENT" ALTER COLUMN "CONTENT_ID" RESTART WITH (SELECT COALESCE(MAX(CONTENT_ID),0)+1 FROM "TJ_CONTENT");
ALTER TABLE "SYS_MENU" ALTER COLUMN "MENU_ID" RESTART WITH (SELECT COALESCE(MAX(MENU_ID),0)+1 FROM "SYS_MENU");
ALTER TABLE "SYS_DICT_TYPE" ALTER COLUMN "DICT_ID" RESTART WITH (SELECT COALESCE(MAX(DICT_ID),0)+1 FROM "SYS_DICT_TYPE");
ALTER TABLE "SYS_DICT_DATA" ALTER COLUMN "DICT_CODE" RESTART WITH (SELECT COALESCE(MAX(DICT_CODE),0)+1 FROM "SYS_DICT_DATA");

-- 读通鉴-古本访问令牌（dutongjian.com 账号 Bearer 令牌，在参数设置页面维护）
INSERT INTO "SYS_CONFIG"(CONFIG_NAME,CONFIG_KEY,CONFIG_VALUE,CONFIG_TYPE,CREATE_BY,CREATE_TIME,REMARK)
SELECT * FROM (VALUES
('读通鉴-古本访问令牌','tongjian.guben.token','','Y','manager',CURRENT_TIMESTAMP,'古本扫描页接口(dutongjian.com /api/guben/view)需要其账号令牌；登录该站后从浏览器本地存储的 token 获取')
) AS V(CONFIG_NAME,CONFIG_KEY,CONFIG_VALUE,CONFIG_TYPE,CREATE_BY,CREATE_TIME,REMARK)
WHERE NOT EXISTS (SELECT 1 FROM "SYS_CONFIG" S WHERE S.CONFIG_KEY = V.CONFIG_KEY);
